CustomField.formula:
if(Client_Rating_Text__c="good", 
	IMAGE("/resource/rating_good", "Good", 20, 20)&"**5pts**", 
	IMAGE("/resource/rating_good", "Good", 20, 20)&" 5pts")&BR()&BR()&
if(Client_Rating_Text__c="average", 
	IMAGE("/resource/rating_average", "Average", 20, 20)&"**0pts**", 
	IMAGE("/resource/rating_average", "Average", 20, 20)&" 0pts")&BR()&BR()&
if(Client_Rating_Text__c="bad", 
	IMAGE("/resource/rating_bad", "Bad", 20, 20)&"**-5pts**",
	IMAGE("/resource/rating_bad", "Bad", 20, 20)&" -5pts")
